const baseEyeColors = ['black','dark grey','grey','light grey','white','dark red','red','light red','dark orange','orange','light orange','dark yellow','yellow','light yellow','dark green','green','light green','dark cyan','cyan','light cyan','dark blue','blue','light blue','dark navy','navy','light navy','dark violet','violet','light violet','dark purple','purple','light purple','dark magenta','magenta','light magenta','dark pink','pink','light pink','dark brown','brown','light brown'];
