  const earMarkup=(x,side,shade)=>'<g transform="translate('+x+' '+headY+') scale('+earScale+') translate('+(-x)+' '+(-headY)+')"><g '+(side==='left'&&(dog.leftEarShape==='up'||dog.leftEarShape==='folded')?'transform="translate('+((x-16)*2)+' 0) scale(-1 1)"':'')+'>'+earShape(x,side,shade)+'</g></g>';
  const tailColor=color(dog.tail), tailLength=dog.tailType==='short'?19:dog.tailType==='long'?49:32;
  const outlinedTail=(d,width)=>'<path d="'+d+'" fill="none" stroke="#000000" stroke-width="'+(width+4)+'" stroke-linecap="round"/><path d="'+d+'" fill="none" stroke="'+tailColor+'" stroke-width="'+width+'" stroke-linecap="round"/>';
  const tail=dog.tailType==='none'?'':dog.tailType==='round poof'?'<circle cx="'+(cx-rx-9)+'" cy="'+(cy-4)+'" r="13" fill="'+tailColor+'" stroke="#000000" stroke-width="2.5"/>':dog.tailType==='curled'||dog.tailType==='thick curled'?outlinedTail('M '+(cx-rx+2)+' '+(cy-4)+' Q '+(cx-rx-20)+' '+(cy-31)+' '+(cx-rx-34)+' '+(cy-14)+' Q '+(cx-rx-47)+' '+(cy+2)+' '+(cx-rx-32)+' '+(cy+7),dog.tailType==='thick curled'?15:9):outlinedTail('M '+(cx-rx+2)+' '+(cy-4)+' Q '+(cx-rx-tailLength*.55)+' '+(cy-19)+' '+(cx-rx-tailLength)+' '+(cy+8),10);
  const tailEnd=dog.tailType==='curled'||dog.tailType==='thick curled'?{x:cx-rx-32,y:cy+7}:{x:cx-rx-tailLength,y:cy+8};
