  const bodyPoofs=dog.poodleFur?'<circle cx="'+(cx-rx*.78)+'" cy="'+cy+'" r="21" fill="'+furColor+'" stroke="#000000" stroke-width="2"/><circle cx="'+(cx+rx*.78)+'" cy="'+cy+'" r="21" fill="'+furColor+'" stroke="#000000" stroke-width="2"/>':'';
