  const renderLeg=(x,i)=>{const top=legTop;if(sleeping){const front=i>=2,direction=front?1:-1,y=cy+bodyRy-2,start=front?x+legW-3:x+3,end=start+direction*34,tip=end+direction*7;return '<path d="M '+start+' '+(y-5)+' L '+end+' '+(y-5)+' Q '+tip+' '+(y-5)+' '+tip+' '+y+' Q '+tip+' '+(y+5)+' '+end+' '+(y+5)+' L '+start+' '+(y+5)+' Z" fill="'+color(legColors[i])+'" stroke="#000000" stroke-width="2" stroke-linejoin="round"/>'}return '<path d="M '+x+' '+top+' L '+(x+legW)+' '+top+' L '+(x+legW)+' '+(ground-4)+' Q '+(x+legW)+' '+ground+' '+(x+legW-5)+' '+ground+' L '+(x-3)+' '+ground+' Q '+(x-7)+' '+ground+' '+(x-5)+' '+(ground-5)+' Z" fill="'+color(legColors[i])+'" stroke="#000000" stroke-width="2" stroke-linejoin="round"/>'};
  const backLegs=visibleLegs.filter(i=>i<2).map(i=>renderLeg(legX[i],i)).join(''), frontLegs=visibleLegs.filter(i=>i>=2).map(i=>renderLeg(legX[i],i)).join('');
