  const noseR=dog.noseSize==='small'?4.5:dog.noseSize==='big'?8:6;
  const dogSize=dog.size||'medium',ageWidth=dog.age==='Puppy'?48:dog.age==='Juvenile'?65:dog.age==='Teen'?82:100,sizeWidth=dogSize==='small'?.82:dogSize==='big'?1.14:1,width=Math.round(ageWidth*sizeWidth),mediumAdult=dog.age==='Adult'&&dogSize==='medium',groundNudge={Puppy:{small:-2,medium:-1,big:0},Juvenile:{small:-1,medium:0,big:1},Teen:{small:-1,medium:0,big:1},Adult:{small:-1,medium:0,big:1}}[dog.age]?.[dogSize]??0;
  const artClass='dog-art dog-age-'+dog.age.toLowerCase()+' dog-size-'+dogSize+(mediumAdult?' adult-medium':'')+(sleeping?' sleeping':'');
  return '<svg class="'+artClass+'" viewBox="0 0 300 '+(sleeping?'210':'184')+'" preserveAspectRatio="xMidYMax meet" data-snout-x="'+(muzzleEnd-8)+'" data-snout-y="'+(headY+snoutW*.35)+'" data-head-x="'+(headX+headR*.8)+'" data-head-y="'+(headY-headR*.7)+'" role="img" aria-label="'+esc(dog.name)+' the dog" style="width:'+width+'%;--ground-nudge:'+groundNudge+'px;--sleep-offset:'+(dog.poodleFur?'9%':'11.4%')+'"><g>'+tail+backLegs+'<ellipse cx="'+cx+'" cy="'+cy+'" rx="'+rx+'" ry="'+bodyRy+'" fill="'+color(dog.body)+'" stroke="#000000" stroke-width="2.5"/>'+markings+bodyPoofs+frontLegs+legPoofs+earMarkup(headX-7,'left',dog.leftEar)+earMarkup(headX+23,'right',dog.rightEar)+'<circle cx="'+headX+'" cy="'+headY+'" r="'+headR+'" fill="'+color(dog.head)+'" stroke="#000000" stroke-width="2.5"/>'+headPoof+'<path d="M '+muzzleStart+' '+(headY+2)+' Q '+(muzzleStart+16*snoutFactor)+' '+(headY-snoutW*.62)+' '+(muzzleEnd)+' '+(headY+2)+' Q '+(muzzleEnd+4)+' '+(headY+snoutW*.62)+' '+(muzzleStart+6)+' '+(headY+snoutW*.7)+' Q '+muzzleStart+' '+(headY+snoutW*.5)+' '+muzzleStart+' '+(headY+2)+' Z" fill="'+color(dog.snout)+'" stroke="#000000" stroke-width="2"/><ellipse cx="'+(muzzleEnd-1)+'" cy="'+(headY+2)+'" rx="'+noseR+'" ry="'+(noseR*.72)+'" fill="'+color(dog.nose)+'" stroke="#000000" stroke-width="1.5"/>'+eyes+'<path d="M '+(headX+12)+' '+(headY+9)+' q 4 5 8 0" fill="none" stroke="#000000" stroke-width="1.5" stroke-linecap="round"/>'+tailPoof+'</g></svg>';
