function dogById(id){return state.dogs.find(d=>d.id===id)}
function ageLabel(dog){return dog.age==='Adult'?'Adult':dog.age+' · '+dog.interactions+'/10'}
function dogBreedOptions(){return '<option value="">Choose a saved breed</option>'+state.breeds.map(b=>'<option value="'+b.id+'" '+(state.selectedBreedId===b.id?'selected':'')+'>'+esc(b.name)+'</option>').join('')}
function breedSnapshot(source){return Object.fromEntries(traitKeys.map(key=>[key,source[key]??defaults[key]]))}
function applyBreedToDraft(breed){if(!breed)return;const name=state.draft.name,gender=state.draft.gender;for(const key of traitKeys)state.draft[key]=breed[key]??defaults[key];state.draft.name=name;state.draft.gender=gender;state.selectedBreedId=breed.id;render()}
function requestBreedName(template){state.pendingBreedTemplate=template;state.modal={type:'breed-name',title:'Turn into Dog Breed',message:'Choose a name for this dog breed.'};showModal()}
function saveBreed(name){const clean=name.trim();if(!clean)return;if(state.breeds.some(b=>b.name.toLowerCase()===clean.toLowerCase())){notify('That dog breed name is already in use.');return}state.breeds.push({id:uid(),name:clean,...state.pendingBreedTemplate});state.pendingBreedTemplate=null;persist();closeModal();render();notify(clean+' added to your dog breeds.')}
function tabs(){return '<nav class="tabs"><button class="tab '+(state.screen==='collection'?'active':'')+'" data-action="collection">Dogs</button><button class="tab '+(state.screen==='breed'?'active':'')+'" data-action="breed">Breed</button><button class="tab '+(state.screen==='competition'?'active':'')+'" data-action="competition">Competitions</button></nav>'}
function header(){return '<header class="topbar"><a class="brand" href="#" data-action="collection"><span class="brand-mark">🐾</span><span class="brand-name">Little Dogs</span></a><div class="top-actions">'+tabs()+'<button class="button ghost small" data-action="restart">Restart</button></div></header>'}
function card(dog){return '<article class="dog-card"><div class="dog-card-top">'+dogSvg(dog)+'</div><div class="dog-card-info"><div class="dog-card-title"><h2>'+esc(dog.name)+'</h2><span class="gender">'+(dog.gender==='Male'?'♂':'♀')+'</span></div><div class="dog-meta">'+esc(ageLabel(dog))+'</div><div class="stat-row"><div class="stat-chip">Strength<b>'+dog.strength+'/50</b></div><div class="stat-chip">Speed<b>'+dog.speed+'/50</b></div></div><div class="card-actions"><button class="button primary small" data-action="open-dog" data-id="'+dog.id+'">Meet</button><button class="button small breed-card-action" data-action="create-dog-breed" data-id="'+dog.id+'">Turn into Dog Breed</button><button class="button small" data-action="sell" data-id="'+dog.id+'">Sell</button></div></div></article>'}
function collection(){const content=state.dogs.length?'<div class="dog-grid">'+state.dogs.map(card).join('')+'</div>':'<div class="empty-state"><div class="paw">🐶</div><h2>Your little pack</h2><p>Make a new friend to get started.</p><button class="button primary" data-action="new-dog">Create your first dog</button></div>';return '<div class="shell">'+header()+'<section class="screen"><div class="section-head"><div><div class="eyebrow">Your pack · '+state.dogs.length+' '+(state.dogs.length===1?'dog':'dogs')+'</div><h1>Meet the pack</h1></div><div class="pack-actions"><button class="button ghost" data-action="color-creator">Color creator</button><button class="button ghost" data-action="competition">Enter competition</button><button class="button primary" data-action="new-dog">＋ Create a dog</button></div></div>'+content+'</section></div>'}
function options(values,selected){return values.map(v=>'<option value="'+esc(v)+'" '+(v===selected?'selected':'')+'>'+esc(v==='coat pink'?'Pink':v[0].toUpperCase()+v.slice(1))+'</option>').join('')}
function fieldHtml(field){const [key,label,type,choices]=field;const val=state.draft[key]??defaults[key]??'';if(key==='patternColor'&&state.draft.pattern==='none')return '';if(key==='poodleFurColor'&&!state.draft.poodleFur)return '';if(type==='checkbox')return '<div class="field full checkbox-field"><label for="f-'+key+'"><input id="f-'+key+'" name="'+key+'" type="checkbox" '+(val?'checked':'')+'> '+label+'</label></div>';if(key==='name')return '<div class="field full"><label for="f-name">Name</label><div class="name-field-row"><input id="f-name" name="name" type="text" maxlength="24" placeholder="Give your dog a name" value="'+esc(val)+'" required><button class="button ghost small" type="button" data-action="randomize-creator-name">Randomize name</button></div></div>';return '<div class="field"><label for="f-'+key+'">'+label+'</label><select id="f-'+key+'" name="'+key+'">'+options(choices,val)+'</select></div>'}
function creator(){const sections=formFields.map(section=>'<section class="form-section"><h3>'+section.section+'</h3><div class="fields">'+section.fields.map(fieldHtml).join('')+'</div></section>').join('');const preview=makeDog({...defaults,...state.draft,name:state.draft.name||'Your dog'});const breedTools=state.breeds.length?'<div class="breed-tools"><label for="saved-breed">Use a dog breed</label><select id="saved-breed">'+dogBreedOptions()+'</select><button class="button ghost small" type="button" data-action="delete-dog-breed" '+(state.selectedBreedId?'':'disabled')+'>Delete breed</button></div>':'';return '<div class="shell">'+(state.started?header():'')+'<section class="screen form-wrap"><div class="form-head"><div><div class="eyebrow">'+(state.createMode==='first'?'A new best friend':'Add to your pack')+'</div><h1 class="page-title">Create your dog</h1></div><div class="creator-head-actions"><button class="button ghost small" type="button" data-action="color-creator">Color creator</button><button class="button ghost small" type="button" data-action="randomize-creator">Randomize</button><button class="button ghost small" type="button" data-action="create-draft-breed">Turn into Dog Breed</button>' +(state.started?'<button class="button ghost" data-action="collection">Cancel</button>':'')+'</div></div><div class="preview-row"><div id="creator-preview">'+dogSvg(preview)+'</div><div><div class="preview-label">Your dog, your way</div><div class="subtle">Every little detail is yours to choose.</div></div></div>'+breedTools+'<form id="creator-form" class="form-card"><div class="creator-grid">'+sections+'</div><div class="form-footer"><span></span><button class="button primary" type="submit">Meet your dog <span aria-hidden="true">→</span></button></div></form></section></div>'}
function colorCreator(){const b=state.colorBuilder,choices=colorChoices(b.type),hex=colorBuilderHex(),savedColors=state.customColors.length?'<div class="custom-color-list">'+state.customColors.map(item=>'<div class="custom-color-row"><span class="color-swatch" style="background:'+item.hex+'"></span><span class="custom-color-name">'+esc(item.name)+'</span><span class="custom-color-type">'+esc(colorTypeLabels[item.type]||item.type)+'</span><button class="button ghost small" type="button" data-action="delete-custom-color" data-id="'+item.id+'">Delete</button></div>').join('')+'</div>':'<p class="subtle">No custom colors yet.</p>';return '<div class="shell">'+(state.started?header():'')+'<section class="screen form-wrap"><div class="form-head"><div><div class="eyebrow">Make it yours</div><h1 class="page-title">Color creator</h1></div><button class="button ghost" type="button" data-action="color-return">Back</button></div><form id="color-form" class="form-card color-form"><div class="creator-grid"><section class="form-section"><h3>New color</h3><div class="field"><label for="color-type">Color type</label><select id="color-type">'+colorTypeOptions(b.type)+'</select></div><div class="field"><label for="color-method">Create with</label><select id="color-method"><option value="mix" '+(b.method==='mix'?'selected':'')+'>Mix two colors</option><option value="custom" '+(b.method==='custom'?'selected':'')+'>Make my own</option></select></div>'+(b.method==='mix'?'<div class="field"><label for="color-a">First color</label><select id="color-a">'+options(choices,b.colorA)+'</select></div><div class="field"><label for="color-b">Second color</label><select id="color-b">'+options(choices,b.colorB)+'</select></div>':'<div class="field"><label for="color-hex">Pick a color</label><input id="color-hex" type="color" value="'+esc(b.hex)+'"></div>')+'<div class="field"><label for="color-name">Color name</label><input id="color-name" maxlength="24" value="'+esc(b.name)+'" placeholder="Name your color" required></div><div class="color-preview-row"><span class="color-swatch large" style="background:'+hex+'"></span><span class="color-preview-name">'+esc(b.name||'Color preview')+'</span><code>'+hex.toUpperCase()+'</code></div><div class="form-footer"><span class="inline-note color-name-note">'+(colorNameTaken(b.name)?'That name is already in use.':'Add it to the selected color list.')+'</span><button class="button primary" type="submit">Add color</button></div></section><section class="form-section saved-colors"><h3>Your custom colors</h3>'+savedColors+'</section></div></form></section></div>'}
function interactionButtons(dog){const asleep=dog.sleeping,young=dog.age==='Puppy',canTrain=dog.age!=='Puppy';if(state.trainMode){return '<div class="action-grid"><button class="action-button" data-action="train-strength" '+(!canTrain||asleep||dog.strength>=50?'disabled':'')+'><span>💪</span>Train strength</button><button class="action-button" data-action="train-speed" '+(!canTrain||asleep||dog.speed>=50?'disabled':'')+'><span>💨</span>Train speed</button><button class="action-button" data-action="back-actions"><span>↩</span>Back</button></div><p class="inline-note">Training improves one skill by a level. Max level: 50.</p>'}
  const actions=[['feed','🥣','Feed'],['treat','❤️','Give treat'],['pet','✋','Pet'],[asleep?'wake':'sleep',asleep?'☀️':'🌙',asleep?'Wake up':'Sleep'],['play','🎾','Play'],['fetch','🥎','Fetch'],['clean','🧽','Clean']];return '<div class="action-grid">'+actions.map(([id,icon,label])=>'<button class="action-button" data-action="'+id+'" '+(asleep&&id!=='wake'?'disabled':'')+'><span>'+icon+'</span>'+label+'</button>').join('')+'<button class="action-button" data-action="train-menu" '+(!canTrain||asleep?'disabled':'')+'><span>🏅</span>Train</button></div>'+(young?'<p class="inline-note">Puppies grow after 10 interactions. Training unlocks at Juvenile.</p>':'')}
function dogMenu(){const dog=dogById(state.currentDog);if(!dog){state.screen='collection';return collection()}return '<div class="shell">'+header()+'<section class="screen"><button class="back-link" data-action="collection">← Back to your dogs</button><div class="menu-layout"><div class="stage '+(dog.sleeping?'sleeping':'')+'" id="dog-stage">'+dogSvg(dog)+'</div><div class="menu-panel"><div class="panel-heading"><div><div class="eyebrow">'+esc(dog.gender)+' dog</div><h1>'+esc(dog.name)+'</h1></div><span class="stage-badge">'+esc(dog.age)+'</span></div><div class="level-bars"><div class="level"><div class="level-top"><span>Strength</span><span>'+dog.strength+' / 50</span></div><div class="meter"><span style="width:'+dog.strength/50*100+'%"></span></div></div><div class="level"><div class="level-top"><span>Speed</span><span>'+dog.speed+' / 50</span></div><div class="meter"><span style="width:'+dog.speed/50*100+'%"></span></div></div></div><div class="subtle">'+esc(ageLabel(dog))+'</div><div class="menu-divider"></div><div class="section-head" style="margin:0 0 11px;align-items:center"><div class="eyebrow" style="margin:0">'+(state.trainMode?'Training':'Spend a little time together')+'</div></div>'+interactionButtons(dog)+'<div class="menu-divider"></div><button class="button danger small" data-action="sell" data-id="'+dog.id+'">Sell '+esc(dog.name)+'</button></div></div></section></div>'}
function eligibleDogs(){return state.dogs.filter(d=>d.age==='Adult')}
function canRandomBreed(){const adults=eligibleDogs();return adults.some(d=>d.gender==='Male')&&adults.some(d=>d.gender==='Female')}
function randomBreedPair(){const adults=eligibleDogs(),males=adults.filter(d=>d.gender==='Male'),females=adults.filter(d=>d.gender==='Female');if(!males.length||!females.length)return null;return [males[Math.floor(Math.random()*males.length)],females[Math.floor(Math.random()*females.length)]]}
function dogChoice(dog,selected){return '<div class="choice-card '+(selected?'selected':'')+'">'+dogSvg(dog)+'<h3>'+esc(dog.name)+' <span class="gender">'+(dog.gender==='Male'?'♂':'♀')+'</span></h3><p>Strength '+dog.strength+' · Speed '+dog.speed+' · '+dog.age+'</p><button class="selection-check" data-action="select-breeder" data-id="'+dog.id+'">'+(selected?'Selected ✓':'Choose dog')+'</button></div>'}
function breedPage(){const eligible=eligibleDogs(),selected=state.breedSelection.map(dogById).filter(Boolean),pairReady=selected.length===2&&selected[0].gender!==selected[1].gender;return '<div class="shell">'+header()+'<section class="screen"><div class="section-head"><div><div class="eyebrow">Grow your pack</div><h1>Breed dogs</h1><p class="subtle">Choose two adult dogs of different genders.</p><div class="breeding-sync-controls"><label><input id="breed-sync-ears" type="checkbox" '+(state.breedSync.ears?'checked':'')+'> Same source for both ears</label><label><input id="breed-sync-legs" type="checkbox" '+(state.breedSync.legs?'checked':'')+'> Same source for all four legs</label><label><input id="breed-sync-eyes" type="checkbox" '+(state.breedSync.eyes?'checked':'')+'> Same source for both eyes</label><label><input id="breed-sync-bodyHead" type="checkbox" '+(state.breedSync.bodyHead?'checked':'')+'> Same source for body and head</label><small>Each enabled group shares one random Parent 1, Parent 2, or mix choice.</small></div><button class="button ghost small" data-action="random-breeders" '+(canRandomBreed()?'':'disabled')+'>Random dogs</button></div></div>'+(eligible.length<2?'<div class="no-dogs">You need two adult dogs to breed. Create another dog or help a puppy grow up.</div>':'<div class="choice-grid">'+eligible.map(d=>dogChoice(d,state.breedSelection.includes(d.id))).join('')+'</div><div class="form-footer"><span class="subtle">'+(selected.length===2&&!pairReady?'Choose dogs of different genders.':selected.length+'/2 selected')+'</span><button class="button primary" data-action="start-breed" '+(pairReady?'':'disabled')+'>Breed dogs</button></div>')+'</section></div>'}
function breedAnimation(){const pair=state.breedSelection.map(dogById).filter(Boolean);return '<div class="shell">'+header()+'<section class="screen"><div class="section-head"><div><div class="eyebrow">A new little life</div><h1>Growing a family</h1></div></div><div class="breed-stage breeding" id="breed-stage"><div class="parent-one">'+dogSvg(pair[0])+'</div><div class="parent-two">'+dogSvg(pair[1])+'</div></div><p class="subtle" style="text-align:center">Love is in the air... <button class="button ghost small" data-action="skip-animation">Skip</button></p></section></div>'}
function breedResult(){const puppy=state.breedResult;return '<div class="shell">'+header()+'<section class="screen form-wrap"><div class="section-head"><div><div class="eyebrow">A new arrival</div><h1>Meet your puppy</h1><p class="subtle">It&#39;s a '+(puppy.gender==='Female'?'girl':'boy')+'!</p></div></div><div class="breed-stage" style="min-height:260px">'+dogSvg(puppy)+'</div><form id="puppy-name-form" class="form-card" style="margin-top:17px"><label for="puppy-name" style="font-weight:700">What will you name this puppy?</label><div class="name-field-row"><input id="puppy-name" class="name-input" name="name" maxlength="24" value="'+esc(puppy.name)+'" required><button class="button ghost small" type="button" data-action="randomize-puppy-name">Randomize name</button></div><div style="display:flex;justify-content:flex-end"><button class="button primary">Welcome to the pack →</button></div></form></section></div>'}
function competitionPage(){const adults=eligibleDogs(),ownMode=state.competition.mode==='My dogs',skillLabel=state.competition.type==='Race'?'Speed':'Strength';const firstOptions=adults.length?adults.map(d=>'<option value="'+d.id+'" '+(state.competition.dog1Id===d.id?'selected':'')+'>'+esc(d.name)+' · '+skillLabel+' '+(state.competition.type==='Race'?d.speed:d.strength)+'</option>').join(''):'<option value="">No adult dogs available</option>';const secondDogs=adults.filter(d=>d.id!==state.competition.dog1Id),secondOptions=secondDogs.length?secondDogs.map(d=>'<option value="'+d.id+'" '+(state.competition.dog2Id===d.id?'selected':'')+'>'+esc(d.name)+' · '+skillLabel+' '+(state.competition.type==='Race'?d.speed:d.strength)+'</option>').join(''):'<option value="">Choose another adult dog</option>';const ready=ownMode?adults.length>1&&state.competition.dog1Id!==state.competition.dog2Id:adults.length>0;const matchFields=ownMode?'<div class="field"><label for="comp-dog-one">First dog</label><select id="comp-dog-one">'+firstOptions+'</select></div><div class="field"><label for="comp-dog-two">Second dog</label><select id="comp-dog-two">'+secondOptions+'</select></div>':'<div class="field"><label for="comp-range">Opponent skill</label><select id="comp-range">'+options(['0-5','5-10','10-20','20-30','30-40','40-50','0-50'],state.competition.range)+'</select></div><div class="field"><label for="comp-dog">Your dog</label><select id="comp-dog">'+(adults.length?adults.map(d=>'<option value="'+d.id+'" '+(state.competition.dogId===d.id?'selected':'')+'>'+esc(d.name)+' · '+(state.competition.type==='Race'?d.speed:d.strength)+' skill</option>').join(''):'<option value="">No adult dogs available</option>')+'</select></div>';return '<div class="shell">'+header()+'<section class="screen"><div class="section-head"><div><div class="eyebrow">A chance to shine</div><h1>Competitions</h1><p class="subtle">Only adult dogs can enter.</p></div></div><div class="competition-layout"><div class="competition-options"><h2>Set up a match</h2><div class="field"><label for="comp-mode">Match mode</label><select id="comp-mode"><option value="Random" '+(state.competition.mode==='Random'?'selected':'')+'>Random opponent</option><option value="My dogs" '+(state.competition.mode==='My dogs'?'selected':'')+'>Two of my dogs</option></select></div><div class="field"><label for="comp-type">Competition</label><select id="comp-type"><option '+(state.competition.type==='Race'?'selected':'')+'>Race</option><option '+(state.competition.type==='Duel'?'selected':'')+'>Duel</option></select></div>'+(ownMode?'<div class="field"><label for="comp-dog-one">First dog</label><select id="comp-dog-one">'+firstOptions+'</select></div><div class="field"><label for="comp-dog-two">Second dog</label><select id="comp-dog-two">'+secondOptions+'</select></div>':'<div class="field"><label for="comp-range">Opponent skill</label><select id="comp-range">'+options(['0-5','5-10','10-20','20-30','30-40','40-50','0-50'],state.competition.range)+'</select></div><div class="field"><label for="comp-dog">Your dog</label><select id="comp-dog">'+(adults.length?adults.map(d=>'<option value="'+d.id+'" '+(state.competition.dogId===d.id?'selected':'')+'>'+esc(d.name)+' · '+(state.competition.type==='Race'?d.speed:d.strength)+' skill</option>').join(''):'<option value="">No adult dogs available</option>')+'</select></div>')+'<button class="button ghost small random-picker" data-action="random-competition-dogs" '+((ownMode?adults.length<2:!adults.length)?'disabled':'')+'>'+(ownMode?'Random dogs':'Random dog')+'</button><button class="button primary" data-action="start-competition" '+(ready?'':'disabled')+'>Start competition →</button>'+(ready?'':'<p class="inline-note">'+(ownMode?'Choose two different adult dogs to compete.':'Create an adult dog or help a puppy grow up to enter.')+'</p>')+'</div><div class="menu-panel"><div class="eyebrow">'+(state.competition.type==='Race'?'The track':'The arena')+'</div><div class="race-field" style="display:grid;place-items:center"><span style="font-size:70px">'+(state.competition.type==='Race'?'🏁':'🐕')+'</span><span class="subtle">Your next challenge awaits</span></div></div></div></section></div>'}
function contestView(){const c=state.contest;if(!c)return competitionPage();if(c.type==='Race')return '<div class="shell">'+header()+'<section class="screen"><div class="section-head"><div><div class="eyebrow">Race day</div><h1>The finish line</h1></div></div><div class="race-field" id="race-field"><div class="race-finish"></div><div class="race-line"></div><div class="race-dog opponent '+(c.running?'racing':'')+'" style="transition-duration:'+c.oppDuration+'ms"><span class="race-tag">'+esc(c.localMatch?c.opponent.name:'Random dog')+'</span>'+dogSvg(c.opponent)+'</div><div class="race-dog you '+(c.running?'racing':'')+'" style="transition-duration:'+c.youDuration+'ms"><span class="race-tag">'+esc(c.localMatch?c.dog.name:'You')+'</span>'+dogSvg(c.dog)+'</div></div>'+(c.result?'<div class="result-card">'+esc(c.result)+'</div><div style="text-align:center;margin-top:12px"><button class="button primary" data-action="competition">Back to competitions</button></div>':'<p class="subtle" style="text-align:center">Ready... set... go! <button class="button ghost small" data-action="skip-animation">Skip</button></p>')+'</section></div>';return '<div class="shell">'+header()+'<section class="screen"><div class="section-head"><div><div class="eyebrow">Duel day</div><h1>Strength showdown</h1></div></div><div class="duel-field"><div class="health-wrap left"><div class="health-label"><span>'+esc(c.localMatch?c.opponent.name:'Random dog')+'</span><span>'+c.oppHealth+' / '+c.oppMax+'</span></div><div class="health-bar"><span style="width:'+c.oppHealth/c.oppMax*100+'%"></span></div></div><div class="health-wrap right"><div class="health-label"><span>'+esc(c.localMatch?c.dog.name:'You · '+c.dog.name)+'</span><span>'+c.youHealth+' / '+c.youMax+'</span></div><div class="health-bar"><span style="width:'+c.youHealth/c.youMax*100+'%"></span></div></div><div class="duel-dog" id="duel-left">'+dogSvg(c.opponent)+'</div><div class="duel-dog" id="duel-right">'+dogSvg(c.dog)+'</div></div>'+(c.result?'<div class="result-card">'+esc(c.result)+'</div><div style="text-align:center;margin-top:12px"><button class="button primary" data-action="competition">Back to competitions</button></div>':'<p class="subtle" style="text-align:center">The duel is on! <button class="button ghost small" data-action="skip-animation">Skip</button></p>')+'</section></div>'}
function render(){if(state.screen!=='dog')stopSleepLoop();if(state.screen==='create')root.innerHTML=creator();else if(state.screen==='colors')root.innerHTML=colorCreator();else if(state.screen==='dog')root.innerHTML=dogMenu();else if(state.screen==='breed')root.innerHTML=breedPage();else if(state.screen==='breed-animation')root.innerHTML=breedAnimation();else if(state.screen==='breed-result')root.innerHTML=breedResult();else if(state.screen==='competition')root.innerHTML=competitionPage();else if(state.screen==='contest')root.innerHTML=contestView();else root.innerHTML=collection();if(state.screen==='dog'&&dogById(state.currentDog)?.sleeping)startSleepLoop(dogById(state.currentDog));if(state.modal)showModal()}
function showModal(){const modal=state.modal;if(document.querySelector('.modal-shade'))return;const shade=document.createElement('div');shade.className='modal-shade';shade.innerHTML=modal.type==='breed-name'?'<form class="modal" id="breed-name-form" role="dialog" aria-modal="true"><h2>'+esc(modal.title)+'</h2><p>'+esc(modal.message)+'</p><input id="breed-name" name="breed-name" maxlength="24" placeholder="Dog breed name" required><div class="modal-actions"><button class="button ghost" type="button" data-action="modal-cancel">Cancel</button><button class="button primary" type="submit">Save breed</button></div></form>':'<div class="modal" role="dialog" aria-modal="true"><h2>'+esc(modal.title)+'</h2><p>'+esc(modal.message)+'</p><div class="modal-actions"><button class="button ghost" data-action="modal-cancel">'+esc(modal.cancel||'Cancel')+'</button><button class="button '+(modal.danger?'danger':'primary')+'" data-action="modal-confirm">'+esc(modal.confirm||'Yes')+'</button></div></div>';root.append(shade)}
function closeModal(){state.modal=null;document.querySelector('.modal-shade')?.remove()}
function notify(message){state.toast=message;document.querySelector('.notice')?.remove();const el=document.createElement('div');el.className='notice';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),2200)}
function clearEffectTimers(){state.effectTimers.forEach(clearTimeout);state.effectTimers=[]}
function stopSleepLoop(){state.sleepTimers.forEach(clearInterval);state.sleepTimers=[];state.sleepDogId=null}
function startSleepLoop(dog){if(state.sleepDogId===dog.id&&state.sleepTimers.length)return;stopSleepLoop();state.sleepDogId=dog.id;const showZ=()=>{const stage=document.querySelector('#dog-stage');if(!stage||!dog.sleeping)return;const z=document.createElement('span');z.className='sleep-z';z.textContent='Z';const art=stage.querySelector('.dog-art');if(art&&!art.classList.contains('adult-medium')){const stageRect=stage.getBoundingClientRect(),artRect=art.getBoundingClientRect();z.style.left=(artRect.left-stageRect.left+Number(art.dataset.headX)/300*artRect.width+14+Math.random()*10)+'px';z.style.top=(artRect.top-stageRect.top+Number(art.dataset.headY)/210*artRect.height-20+Math.random()*8)+'px'}else{z.style.left=(68+Math.random()*14)+'%';z.style.top=(22+Math.random()*10)+'%'}stage.append(z);setTimeout(()=>z.remove(),1900)};showZ();state.sleepTimers=[setInterval(showZ,2000)]}
function advanceAge(dog){if(dog.age==='Adult')return;dog.interactions=(dog.interactions||0)+1;if(dog.interactions>=10){dog.interactions=0;dog.age=dog.age==='Puppy'?'Juvenile':dog.age==='Juvenile'?'Teen':'Adult';notify(dog.name+' grew up! Now '+dog.age+'.')}}
function effectEmoji(emoji,cls='heart',count=1){const stage=document.querySelector('#dog-stage');if(!stage)return;for(let i=0;i<count;i++){const el=document.createElement('span');el.className='effect '+cls;el.textContent=emoji;el.style.left=(35+Math.random()*35)+'%';el.style.top=(28+Math.random()*20)+'%';el.style.animationDelay=(i*.11)+'s';stage.append(el);state.effectTimers.push(setTimeout(()=>el.remove(),1900+i*110))}}
function doInteraction(action){const dog=dogById(state.currentDog);if(!dog)return;if(dog.sleeping&&action!=='wake')return;if(action==='wake'){dog.sleeping=false;state.sleepTimers.forEach(clearInterval);state.sleepTimers=[];state.sleepDogId=null;persist();render();notify(dog.name+' woke up.');return}
  if(action==='sleep')dog.sleeping=true;const previousAge=dog.age;advanceAge(dog);persist();if(action==='sleep'){render();return}if(previousAge!==dog.age)render();
  if(action==='pet'||action==='treat')effectEmoji('♥','heart',action==='treat'?2:1);
  if(action==='feed'||action==='treat'){const stage=document.querySelector('#dog-stage');if(stage){const art=stage.querySelector('.dog-art');if(art){const stageRect=stage.getBoundingClientRect(),point=art.createSVGPoint();point.x=Number(art.dataset.snoutX);point.y=Number(art.dataset.snoutY);const snout=point.matrixTransform(art.getScreenCTM()),snoutX=snout.x-stageRect.left,snoutY=snout.y-stageRect.top;for(let i=0;i<9;i++){const crumb=document.createElement('span');crumb.className='effect crumb';crumb.textContent='•';crumb.style.left=((snoutX-7+Math.random()*14)/stageRect.width*100)+'%';crumb.style.top=((snoutY-5+Math.random()*10)/stageRect.height*100)+'%';stage.append(crumb);setTimeout(()=>crumb.remove(),650)}}}}
  if(action==='play'){const stage=document.querySelector('#dog-stage');stage?.classList.remove('playing');void stage?.offsetWidth;stage?.classList.add('playing');setTimeout(()=>stage?.classList.remove('playing'),1700)}
  if(action==='fetch'){const stage=document.querySelector('#dog-stage');stage?.classList.add('fetching');const ball=document.createElement('span');ball.className='fetch-ball';ball.textContent='🥎';stage?.append(ball);setTimeout(()=>{stage?.classList.remove('fetching');ball.remove()},2600)}
  if(action==='clean'){const stage=document.querySelector('#dog-stage');if(stage){const sponge=document.createElement('span');sponge.className='sponge';sponge.textContent='🧽';stage.append(sponge);const bubbles=setInterval(()=>{if(!sponge.isConnected)return;const stageRect=stage.getBoundingClientRect(),spongeRect=sponge.getBoundingClientRect();for(let i=0;i<2;i++){const bubble=document.createElement('span');bubble.className='clean-bubble';bubble.textContent='🫧';bubble.style.left=(spongeRect.left-stageRect.left+spongeRect.width/2-12+(Math.random()*46-23))+'px';bubble.style.top=(spongeRect.top-stageRect.top+spongeRect.height/2-12+(Math.random()*38-19))+'px';stage.append(bubble);setTimeout(()=>bubble.remove(),650)}} ,140);setTimeout(()=>{clearInterval(bubbles);sponge.remove()},10000)}}
  if(state.screen==='dog'&&previousAge===dog.age){const stage=document.querySelector('#dog-stage');if(stage){const old=stage.querySelector('.dog-art');const shell=document.createElement('div');shell.innerHTML=dogSvg(dog);old?.replaceWith(shell.firstElementChild);if(dog.sleeping)stage.classList.add('sleeping')}const badge=document.querySelector('.stage-badge');if(badge)badge.textContent=dog.age;const subtle=document.querySelector('.menu-panel .subtle');if(subtle)subtle.textContent=ageLabel(dog);}
}
function train(skill){const dog=dogById(state.currentDog);if(!dog||dog.sleeping||dog.age==='Puppy')return;if(dog[skill]>=50){notify('That skill is already at max level.');return}dog[skill]++;advanceAge(dog);persist();render();notify(dog.name+' trained '+(skill==='strength'?'strength':'speed')+' to '+dog[skill]+'.')}
function mixColors(a,b){const ca=color(a),cb=color(b);return '#'+[1,3,5].map(i=>Math.round((parseInt(ca.slice(i,i+2),16)+parseInt(cb.slice(i,i+2),16))/2).toString(16).padStart(2,'0')).join('')}
const colorKeys=new Set(['head','body','leftEar','rightEar','frontLeftLeg','frontRightLeg','backLeftLeg','backRightLeg','tail','snout','leftEye','rightEye','nose','patternColor']);
function puppyFrom(a,b){const traits={},groups={leftEar:'ears',rightEar:'ears',frontLeftLeg:'legs',frontRightLeg:'legs',backLeftLeg:'legs',backRightLeg:'legs',leftEye:'eyes',rightEye:'eyes',head:'bodyHead',body:'bodyHead'},sharedPicks={};for(const group of ['ears','legs','eyes','bodyHead'])if(state.breedSync[group])sharedPicks[group]=Math.floor(Math.random()*3);for(const key of traitKeys){if(key==='poodleFur'||key==='poodleFurColor')continue;if(colorKeys.has(key)){const group=groups[key],pick=group&&state.breedSync[group]?sharedPicks[group]:Math.floor(Math.random()*3);traits[key]=pick===0?a[key]:pick===1?b[key]:mixColors(a[key],b[key])}else traits[key]=Math.random()<.5?a[key]:b[key]}if(a.pattern!=='none'&&b.pattern==='none'&&traits.pattern!=='none')traits.patternColor=a.patternColor;else if(b.pattern!=='none'&&a.pattern==='none'&&traits.pattern!=='none')traits.patternColor=b.patternColor;const gender=Math.random()<.5?'Male':'Female';if(a.poodleFur&&b.poodleFur){const colors=[a.poodleFurColor||defaults.poodleFurColor,b.poodleFurColor||defaults.poodleFurColor,mixColors(a.poodleFurColor||defaults.poodleFurColor,b.poodleFurColor||defaults.poodleFurColor)];traits.poodleFur=true;traits.poodleFurColor=colors[Math.floor(Math.random()*colors.length)]}else if(a.poodleFur||b.poodleFur){const parent=a.poodleFur?a:b;traits.poodleFur=Math.random()<.5;traits.poodleFurColor=parent.poodleFurColor||defaults.poodleFurColor}else{traits.poodleFur=false;traits.poodleFurColor=defaults.poodleFurColor}return {...makeDog({...traits,name:randomDogName(gender),gender},'Puppy'),strength:Math.floor((a.strength+b.strength)/4),speed:Math.floor((a.speed+b.speed)/4)}}
function finishBreeding(){if(state.breedTimer){clearTimeout(state.breedTimer);clearInterval(state.breedTimer);state.breedTimer=null}state.screen='breed-result';render()}
function startBreeding(){const [a,b]=state.breedSelection.map(dogById);if(!a||!b||a.gender===b.gender)return;state.breedResult=puppyFrom(a,b);state.screen='breed-animation';render();state.breedTimer=setTimeout(()=>{let elapsed=0;state.breedTimer=setInterval(()=>{const stage=document.querySelector('#breed-stage');if(stage){for(let i=0;i<4;i++){const heart=document.createElement('span');heart.className='breed-heart';heart.textContent='♥';heart.style.left=(30+Math.random()*40)+'%';heart.style.top=(18+Math.random()*52)+'%';heart.style.animationDelay=(Math.random()*.2)+'s';stage.append(heart);setTimeout(()=>heart.remove(),1200)}}elapsed+=2;if(elapsed>=10)finishBreeding()},2000)},1500)}
function parseRange(range){const [min,max]=range.split('-').map(Number);return {min,max}}
function randomDog(name,skill,type){const random=values=>values[Math.floor(Math.random()*values.length)];const traits={};for(const key of traitKeys){const field=formFields.flatMap(section=>section.fields).find(item=>item[0]===key);traits[key]=field[2]==='checkbox'?Math.random()<.5:random(field[3]||[defaults[key]])}const dog=makeDog({...traits,name,gender:Math.random()<.5?'Male':'Female'});dog.strength=type==='Duel'?skill:Math.floor(Math.random()*31);dog.speed=type==='Race'?skill:Math.floor(Math.random()*31);return dog}
function finishRace(c){if(state.contest!==c||c.result)return;state.contestTimer=null;c.running=false;if(c.youDuration<c.oppDuration){c.result=c.localMatch?c.dog.name+' won!':'You won!';c.dog.speed=Math.min(50,c.dog.speed+1+Math.floor(Math.random()*5))}else if(c.youDuration===c.oppDuration){c.result='It was a tie!';c.dog.speed=Math.min(50,c.dog.speed+1);if(c.localMatch)c.opponent.speed=Math.min(50,c.opponent.speed+1)}else{c.result=c.localMatch?c.opponent.name+' won!':'You lost!';if(c.localMatch)c.opponent.speed=Math.min(50,c.opponent.speed+1+Math.floor(Math.random()*5))}persist();render()}
function startCompetition(){if(state.contestTimer){clearTimeout(state.contestTimer);clearInterval(state.contestTimer);state.contestTimer=null}const localMatch=state.competition.mode==='My dogs';let dog,opponent,skill=null;if(localMatch){dog=dogById(state.competition.dog1Id);opponent=dogById(state.competition.dog2Id);if(!dog||!opponent||dog.id===opponent.id)return}else{dog=dogById(state.competition.dogId)||eligibleDogs()[0];if(!dog)return;const range=parseRange(state.competition.range);skill=Math.floor(Math.random()*(range.max-range.min+1))+range.min;opponent=randomDog('Random dog',skill,state.competition.type)}if(state.competition.type==='Race'){const youDuration=6500-dog.speed*100,oppDuration=6500-opponent.speed*100;state.contest={type:'Race',localMatch,dog,opponent,skill,youDuration,oppDuration,running:false,result:''};state.screen='contest';render();const contest=state.contest;requestAnimationFrame(()=>{if(state.contest!==contest||contest.result)return;contest.running=true;document.querySelectorAll('.race-dog').forEach(el=>el.classList.add('racing'))});state.contestTimer=setTimeout(()=>finishRace(contest),Math.max(youDuration,oppDuration)+1000)}else{const youMax=50+dog.strength*10,oppMax=50+opponent.strength*10;state.contest={type:'Duel',localMatch,dog,opponent,skill,youMax,oppMax,youHealth:youMax,oppHealth:oppMax,result:'',lastAttacker:Math.random()<.5?'you':'opponent'};state.screen='contest';render();state.contestTimer=setInterval(()=>duelTurn(),1000)}}
function duelDamage(dog){return Math.max(1,Math.floor(Math.random()*(21+dog.strength)))}
function finishDuel(c){if(state.contest!==c||c.result)return;state.contestTimer=null;c.finishing=false;if(c.oppHealth===0){c.result=c.localMatch?c.dog.name+' won!':'You won!';c.dog.strength=Math.min(50,c.dog.strength+1+Math.floor(Math.random()*5))}else{c.result=c.localMatch?c.opponent.name+' won!':'You lost!';if(c.localMatch)c.opponent.strength=Math.min(50,c.opponent.strength+1+Math.floor(Math.random()*5))}persist();render()}
function duelTurn(){const c=state.contest;if(!c||c.result||c.finishing)return;const attacker=c.lastAttacker==='you'?'opponent':'you';c.lastAttacker=attacker;const dog=attacker==='you'?c.dog:c.opponent,damage=duelDamage(dog);if(attacker==='you')c.oppHealth=Math.max(0,c.oppHealth-damage);else c.youHealth=Math.max(0,c.youHealth-damage);render();const target=document.querySelector(attacker==='you'?'#duel-right':'#duel-left');target?.classList.add(attacker==='you'?'attack-right':'attack-left');setTimeout(()=>target?.classList.remove('attack-right','attack-left'),220);if(c.youHealth===0||c.oppHealth===0){c.finishing=true;clearInterval(state.contestTimer);state.contestTimer=setTimeout(()=>finishDuel(c),500)}}
function skipAnimation(){if(state.screen==='breed-animation'){finishBreeding();return}const c=state.contest;if(!c||c.result)return;if(state.contestTimer){clearTimeout(state.contestTimer);clearInterval(state.contestTimer);state.contestTimer=null}if(c.type==='Race'){finishRace(c);return}c.finishing=false;while(c.youHealth>0&&c.oppHealth>0){const attacker=c.lastAttacker==='you'?'opponent':'you';c.lastAttacker=attacker;const damage=duelDamage(attacker==='you'?c.dog:c.opponent);if(attacker==='you')c.oppHealth=Math.max(0,c.oppHealth-damage);else c.youHealth=Math.max(0,c.youHealth-damage)}finishDuel(c)}
function stopTransientTimers(){if(state.breedTimer){clearTimeout(state.breedTimer);clearInterval(state.breedTimer);state.breedTimer=null}if(state.contestTimer){clearTimeout(state.contestTimer);clearInterval(state.contestTimer);state.contestTimer=null}}
function randomizeDraft(){for(const section of formFields)for(const [key,,type,choices] of section.fields){if(key==='name')continue;state.draft[key]=type==='checkbox'?Math.random()<.5:choices[Math.floor(Math.random()*choices.length)]}state.draft.name=randomDogName(state.draft.gender);render()}
