  if(action==='delete-custom-color'){const item=state.customColors.find(c=>c.id===id);if(item){for(const dog of state.dogs)for(const key of traitKeys)if(dog[key]===item.name)dog[key]=item.hex;if(state.breedResult)for(const key of traitKeys)if(state.breedResult[key]===item.name)state.breedResult[key]=item.hex;for(const breed of state.breeds)for(const key of traitKeys)if(breed[key]===item.name)breed[key]=item.hex;for(const key of traitKeys)if(state.draft[key]===item.name)state.draft[key]=defaults[key];if(state.colorBuilder.colorA===item.name)state.colorBuilder.colorA=baseCoatColors[0];if(state.colorBuilder.colorB===item.name)state.colorBuilder.colorB=baseCoatColors[0];state.customColors=state.customColors.filter(c=>c.id!==id);refreshColorChoices();persist();render();notify(item.name+' deleted.')}}
  if(action==='randomize-creator')randomizeDraft()
  if(action==='create-draft-breed')requestBreedName(breedSnapshot({...defaults,...state.draft}))
  if(action==='create-dog-breed'){const dog=dogById(id);if(dog)requestBreedName(breedSnapshot(dog))}
  if(action==='delete-dog-breed'){const breed=state.breeds.find(b=>b.id===state.selectedBreedId);if(breed)state.modal={title:'Delete '+breed.name+'?',message:'This will remove this saved dog breed. Dogs already made from it will not change.',confirm:'Delete breed',danger:true,onConfirm:()=>{state.breeds=state.breeds.filter(b=>b.id!==breed.id);state.selectedBreedId='';persist();render();notify(breed.name+' deleted.')}};showModal()}
  if(action==='randomize-creator-name'){state.draft.name=randomDogName(state.draft.gender);const input=root.querySelector('#f-name');if(input)input.value=state.draft.name;updatePreview()}
  if(action==='randomize-puppy-name'&&state.breedResult){state.breedResult.name=randomDogName(state.breedResult.gender);const input=root.querySelector('#puppy-name');if(input)input.value=state.breedResult.name}
  if(action==='new-dog'){state.createMode='add';state.selectedBreedId='';state.draft={...defaults,name:'',gender:'Male'};state.screen='create';render()}
