  if(action==='restart'){state.modal={title:'Start over?',message:'This will remove every dog and all saved progress, and return to the first dog creator.',confirm:'Restart game',danger:true,onConfirm:()=>{state.dogs=[];state.breeds=[];state.selectedBreedId='';state.customColors=[];refreshColorChoices();state.started=false;state.screen='create';state.currentDog=null;state.breedSelection=[];state.contest=null;state.draft={...defaults,name:'',gender:'Male'};persist();render()}};showModal()}
  if(action==='modal-cancel'){closeModal()}
  if(action==='modal-confirm'){const fn=state.modal?.onConfirm;closeModal();fn?.()}
