  if(action==='train-speed')train('speed')
  if(action==='breed'){state.breedSelection=[];state.screen='breed';render()}
  if(action==='select-breeder'){const dog=dogById(id);if(!dog)return;if(state.breedSelection.includes(id))state.breedSelection=state.breedSelection.filter(x=>x!==id);else if(state.breedSelection.length<2)state.breedSelection.push(id);render()}
